package Vxiyan.CritClasses;

import java.util.HashMap;
import java.util.Map;

/**
 * Abstract base class for game event system handling different event types.
 * Manages event-specific data and provides common interface for all event handlers.
 */
public abstract class Event {
    protected String name;
    public enum type {BIPATH, POLYPATH, BASIC_BATTLE, ADV_BATTLE, SHOP}
    protected type eventType;
    protected Map<String, Object> events = new HashMap<>();

    /**
     * Constructor initializes event with name and type.
     * Automatically populates event-specific data based on event type.
     * @param name Event identifier string
     * @param givenType Type of event (BIPATH, POLYPATH, BASIC_BATTLE, ADV_BATTLE, SHOP)
     */
    public Event(String name, type givenType) {
        this.name = name;
        this.eventType = givenType;

        // Initialize events based on type
        if (this.eventType == type.BIPATH) {
            // Path traversal event data with single string answers
            events.put("Wormhole", "jump over");
            events.put("Crossroads", "dark");
            events.put("Mimic_Chest", "open");
            events.put("TrueMimicChest", "run away");
            // ... (19 additional path events)
        } else if (this.eventType == type.POLYPATH) {
            // Multi-path event data with string arrays for multiple options
            events.put("three_tunnels", new String[]{"left path leads to gold", "middle path triggers a trap", "right path goes back"});
            events.put("four_doors", new String[]{"red door burns", "blue door floods", "green door heals", "yellow door opens the exit"});
            // ... (10 additional poly-path events)
        } else if (this.eventType == type.BASIC_BATTLE) {
            // Basic battle events with health/damage arrays
            events.put("goblin", new String[]{"50", "10"});
            events.put("slime", new String[]{"30", "5"});
            events.put("bandit", new String[]{"70", "15"});
            // ... (10 additional basic battle enemies)
        } else if (this.eventType == type.ADV_BATTLE) {
            // Advanced battle events with health/damage arrays and difficulty levels
            events.put("dragon", new String[]{"200", "35", "hard"});
            events.put("orc_warlord", new String[]{"150", "25", "medium"});
            events.put("lich", new String[]{"120", "40", "expert"});
            // ... (15 additional advanced battle enemies)
        } else {
            Logger.println("Shop Incoming!");
        }
    }

    /**
     * Retrieves the event name.
     * @return Event identifier string
     */
    public String getName() {
        return name;
    }

    /**
     * Retrieves the event type.
     * @return Enum value representing event category
     */
    public type getEventType() {
        return eventType;
    }

    /**
     * Abstract method for handling specific event logic.
     * Must be implemented by concrete event classes.
     */
    protected abstract void handle();
}
```

